#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[11];
    int marks;
} Rec;

static int cmp(const void *a, const void *b)
{
    const Rec *x = (const Rec *)a;
    const Rec *y = (const Rec *)b;
    if (x->marks != y->marks) {
        return y->marks - x->marks;
    }
    return strcmp(x->name, y->name);
}

int main(void)
{
    Rec r[100];
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%10s %d", r[i].name, &r[i].marks) != 2) {
            return 1;
        }
    }
    qsort(r, (size_t)n, sizeof(Rec), cmp);
    printf("%-10s %5s\n", "Name", "Marks");
    puts("----------------");
    for (int i = 0; i < n; i++) {
        printf("%-10s %5d\n", r[i].name, r[i].marks);
    }
    return 0;
}
